<script setup lang="ts">
import { computed } from 'vue';
import { Head, Link, useForm } from '@inertiajs/vue3';
import AppLayout from '../../layouts/AppLayout.vue';
import { useConfirmedMutation } from '../../composables/confirmedMutation';
const confirmation = useConfirmedMutation();
const { pending: confirming } = confirmation;
type Program = { id:number; nomor:string; revisi:number; tgl_mulai:string; tgl_selesai:string; id_trainer:number; id_asisten:number; durasi_hari:number };
type History = { team: {trainer_lama:string|null;trainer_baru:string|null;asisten_lama:string|null;asisten_baru:string|null}|null; id:number; tgl_mulai_lama:string; tgl_selesai_lama:string; tgl_mulai_baru:string; tgl_selesai_baru:string; id_trainer_lama:number; id_trainer_baru:number; id_asisten_lama:number; id_asisten_baru:number; alasan:string; created_date:string; nm_lengkap:string; surat_lama:number|null; surat_baru:number|null; evidence:{id:number;nama_file:string}[]; revisions:{id:number;id_quotation:number;revisi:number}[] };
const props=defineProps<{program:Program;history:History[];version:string;requestId:string;reason:string|null;canManage:boolean;minimum:string;trainers:{id:number;nama:string}[];assistants:{id:number;nama:string}[];impact:{quotation:number;peserta:number;so:number;surat:number;lunas:number}}>();
const form=useForm({request_id:props.requestId,version:props.version,tgl_mulai:props.program.tgl_mulai,id_trainer:props.program.id_trainer,id_asisten:props.program.id_asisten,alasan:'',evidence:[] as File[]});
const dateChanged=computed(()=>form.tgl_mulai!==props.program.tgl_mulai);
const endDate=computed(()=>{const d=new Date(form.tgl_mulai+'T00:00:00Z');if(Number.isNaN(d.getTime()))return '';d.setUTCDate(d.getUTCDate()+props.program.durasi_hari-1);return d.toISOString().slice(0,10);});
function save(){return confirmation.form(form,'post',`/penjualan-program/${props.program.id}/reschedule`,{title:`Reschedule ${props.program.nomor}?`,text:`Jadwal ${props.program.tgl_mulai} menjadi ${form.tgl_mulai} s.d. ${endDate.value}. Terdampak: ${props.impact.quotation} Quotation, ${props.impact.peserta} peserta dan ${props.impact.so} Sales Order. Perubahan mengikuti proses konfirmasi ulang.`,confirmLabel:'Ya, reschedule',danger:true},{forceFormData:true,preserveState:'errors'});}
</script>
<template>
<Head title="Reschedule dan Riwayat"/><AppLayout title="Reschedule"><header class="page-header"><div><h1>Reschedule {{program.nomor}}<span v-if="program.revisi">-rev{{program.revisi}}</span></h1><p>{{program.tgl_mulai}} s.d. {{program.tgl_selesai}} · Durasi {{program.durasi_hari}} hari</p></div><Link :href="`/penjualan-program/${program.id}`">Kembali ke program</Link></header>
<p v-if="reason" class="notice" role="status">{{reason}}</p>
<form v-if="canManage && !reason" class="panel stack" @submit.prevent="save"><h2>Jadwal dan tim baru</h2><p>Hanya tanggal, trainer, dan asisten yang berubah. Biaya, waktu, lokasi, dan durasi tetap. Evidence wajib.</p><div class="form-grid"><label>Tanggal mulai baru<input v-model="form.tgl_mulai" type="date" :min="minimum" required/></label><p>Selesai: {{endDate}}</p><label>Trainer<select v-model="form.id_trainer" required><option v-for="x in trainers" :key="x.id" :value="x.id">{{x.nama}}</option></select></label><label>Asisten<select v-model="form.id_asisten" required><option v-for="x in assistants" :key="x.id" :value="x.id">{{x.nama}}</option></select></label></div><label>Alasan<textarea v-model="form.alasan" maxlength="500" required/></label><label>Evidence JPG/PNG/PDF/DOC/DOCX, maksimal 5 MB/file<input type="file" multiple accept=".jpg,.jpeg,.png,.pdf,.doc,.docx" required @change="form.evidence=Array.from(($event.target as HTMLInputElement).files || [])"/></label><ul><li v-for="f in form.evidence" :key="f.name">{{f.name}}</li></ul><section class="notice"><h2>Dampak sebelum simpan</h2><p>{{dateChanged?impact.quotation:0}} quotation dan {{dateChanged?impact.so:0}} SO naik revisi; {{dateChanged?impact.peserta:0}} peserta perlu konfirmasi ulang. {{impact.surat}} Surat Tugas diganti.</p><p>{{impact.lunas}} peserta tercakup Invoice lunas. Invoice tetap; peserta tidak ikut dapat diproses Refund. Sales mengirim ulang PDF dan link baru.</p></section><p v-for="e in form.errors" :key="e" class="error" role="alert">{{e}}</p><progress v-if="form.progress" :value="form.progress.percentage" max="100" aria-label="Progres evidence"/><button class="primary" :disabled="form.processing">Simpan Reschedule</button></form>
<section class="panel"><h2>Riwayat Reschedule ({{history.length}})</h2><p v-if="!history.length">Belum ada Reschedule.</p><article v-for="h in history" :key="h.id" class="panel"><h3>{{h.created_date}} · {{h.nm_lengkap}}</h3><p>Jadwal lama: {{h.tgl_mulai_lama}} s.d. {{h.tgl_selesai_lama}}; trainer {{h.team?.trainer_lama || `ID ${h.id_trainer_lama}`}}, asisten {{h.team?.asisten_lama || `ID ${h.id_asisten_lama}`}}.</p><p>Jadwal baru: {{h.tgl_mulai_baru}} s.d. {{h.tgl_selesai_baru}}; trainer {{h.team?.trainer_baru || `ID ${h.id_trainer_baru}`}}, asisten {{h.team?.asisten_baru || `ID ${h.id_asisten_baru}`}}.</p><p>{{h.alasan}}</p><ul><li v-for="f in h.evidence" :key="f.id"><a :href="`/documents/reschedule/${f.id}`">{{f.nama_file}}</a></li></ul><a :href="`/penjualan-program/${program.id}/reschedule/${h.id}/pdf`" target="_blank" rel="noopener">PDF program sebelum perubahan</a><p v-for="q in h.revisions" :key="q.id">Quotation #{{q.id_quotation}} versi {{q.revisi}} tersimpan.</p><p v-if="h.surat_baru">Surat Tugas #{{h.surat_lama}} diganti dengan #{{h.surat_baru}}.</p></article></section>
</AppLayout>
</template>
